// contactOrigin is how the list shows where a contact lives.
type contactOrigin struct {
	Label string
	Title string
	// Color is the account's, for a contact living on one.
	Color string
}

// contactCardHome names where a contact lives, its Stored in: Gofer Local,
// or the account, with its color, and the address book in the title.
func contactCardHome(ctx context.Context, contact models.Contact, accounts []models.Account) contactOrigin {
	home := strings.TrimSpace(contact.StoredIn)
	if home == "" || home == "local" {
		label := i18n.T(ctx, "contacts.origin.local")
		return contactOrigin{Label: label, Title: i18n.T(ctx, "contacts.stored_in_title", "place", label)}
	}
	for _, account := range accounts {
		if home == "account:"+account.ID {
			label := accountContactOriginLabel(ctx, account)
			return contactOrigin{Label: label, Title: i18n.T(ctx, "contacts.stored_in_title", "place", label), Color: account.Color}
		}
		for _, book := range account.ContactAddressBooks {
			if home == "book:"+book.ID {
				label := accountContactOriginLabel(ctx, account)
				return contactOrigin{Label: label, Title: i18n.T(ctx, "contacts.stored_in_title", "place", label+" / "+contactAddressBookDisplayName(ctx, book)), Color: account.Color}
			}
		}
	}
	label := i18n.T(ctx, "contacts.origin.unavailable_account")
	return contactOrigin{Label: label, Title: label}
}

// contactCardDate is the date a contact card shows: when the contact was last
// seen in mail, or else when it was added, with what it means.
func contactCardDate(ctx context.Context, contact models.Contact) (string, string) {
	if trashed := strings.TrimSpace(contact.TrashedAt); trashed != "" {
		return trashed, i18n.T(ctx, "contacts.card.trashed", "date", trashed, "purge", contact.TrashPurgeAt)
	}
	if seen := strings.TrimSpace(contact.LastSeenAt); seen != "" {
		return seen, i18n.T(ctx, "contacts.card.last_seen", "date", seen)
	}
	if added := strings.TrimSpace(contact.CreatedAt); added != "" {
		return added, i18n.T(ctx, "contacts.card.added", "date", added)
	}
	return "", ""
}

